/* Overriding copy icon color to be neutral/dark instead of primary blue */
:host ::ng-deep .ant-typography-copy {
    color: rgba(0, 0, 0, 0.45);
}
:host ::ng-deep .ant-typography-copy:hover {
    color: rgba(0, 0, 0, 0.75);
}

.green-bg {

/* New styles for read-only user data view */
.field-label {
    font-size: 12px;
    color: rgba(0, 0, 0, 0.45);
    margin-bottom: 2px; /* Close to the value */
    font-weight: 500;
    text-transform: uppercase; /* Optional: distinct look for label */
    letter-spacing: 0.5px;
}

.field-value {
    font-size: 14px;
    color: rgba(0, 0, 0, 0.85);
    word-wrap: break-word;
    white-space: pre-wrap;
    line-height: 1.5;
    padding-bottom: 8px; /* Spacing for the next row if needed, mainly handled by gutter though */
    min-height: 22px; /* Ensure empty fields take up space or align correctly */
}
